with seed(slug, name, department, subcategory, price_bdt, compare_at_bdt, description, sku, materials, swatches) as (
  values
    ('marlow-table-lamp','Marlow Table Lamp','lamps','table-lamps',420, null,'A sculptural ceramic base and softly tapered shade bring a warm, quiet glow to bedside tables and reading corners.','CL-MARLOW','["Ceramic","Linen","Brass"]'::jsonb,'[{"label":"Brushed Brass","color":"#C9A362"},{"label":"Ivory","color":"#E8E0D4"}]'::jsonb),
    ('solis-pendant','Solis Dome Pendant','lamps','pendant-lights',680, null,'A generous spun-metal shade casts focused, welcoming light over kitchen islands and dining tables.','CL-SOLIS','["Brass","Metal"]'::jsonb,'[{"label":"Warm Brass","color":"#C9A362"},{"label":"Chalk","color":"#F0EBE0"}]'::jsonb),
    ('oslo-side-table','Oslo Side Table','tables','side-tables',540, null,'A compact oak table with a rounded top, sized for a favourite lamp, a book, and a cup of tea.','CL-OSLO','["Oak Wood"]'::jsonb,'[{"label":"Natural Oak","color":"#C8A96E"},{"label":"Smoked Oak","color":"#6B4B32"}]'::jsonb),
    ('cleo-wall-sconce','Cleo Wall Sconce','lamps','wall-lights',360, null,'A petite brass wall light with a softly diffused glow for hallways, bedside reading, and layered lighting.','CL-CLEO','["Brass"]'::jsonb,'[{"label":"Brushed Brass","color":"#C9A362"},{"label":"Matte Black","color":"#3A3530"}]'::jsonb),
    ('milo-console-table','Milo Console Table','tables','console-tables',920, null,'A slim oak console creates a considered landing spot for keys, a mirror, and a small accent lamp.','CL-MILO','["Oak Wood"]'::jsonb,'[{"label":"Natural Oak","color":"#C8A96E"},{"label":"Walnut","color":"#6B4B32"}]'::jsonb),
    ('iris-dining-table','Iris Dining Table','tables','dining-tables',1550,1800,'A clean-lined solid ash table with room for shared meals, good conversation, and a beautiful pendant overhead.','CL-IRIS','["Natural Ash","Walnut"]'::jsonb,'[{"label":"Natural Ash","color":"#D4B896"},{"label":"Walnut","color":"#6B4B32"}]'::jsonb),
    ('nora-table-lamp','Nora Glass Table Lamp','lamps','table-lamps',480, null,'Clear, hand-finished glass and a linen shade create an airy accent that works from desk to bedside.','CL-NORA','["Glass","Linen"]'::jsonb,'[{"label":"Clear Glass","color":"#E8E0D4"},{"label":"Smoked Glass","color":"#6B7A8D"}]'::jsonb),
    ('arc-floor-lamp','Arc Floor Lamp','lamps','floor-lamps',1150, null,'A slender arched stem and generous linen shade bring warm, adjustable light beside a reading nook.','CL-ARC','["Marble","Linen","Metal"]'::jsonb,'[{"label":"Travertine & Linen","color":"#E8E0D4"},{"label":"Marble & Charcoal","color":"#3A3530"}]'::jsonb),
    ('solene-wall-mirror','Solene Arched Wall Mirror','mirrors','wall-mirrors',680, null,'A softly arched mirror framed in warm brushed brass, made to brighten an entryway or dressing space.','CL-SOLENE','["Glass","Brass"]'::jsonb,'[{"label":"Brushed Brass","color":"#C9A362"},{"label":"Matte Black","color":"#3A3530"}]'::jsonb),
    ('isla-linen-lamp-shade','Isla Linen Lamp Shade','shades','lamp-shades',180, null,'A tapered natural-linen shade that gives table lamps a warm, softly diffused glow.','CL-ISLA','["Natural Linen"]'::jsonb,'[{"label":"Natural Linen","color":"#F0EBE0"},{"label":"Warm Sand","color":"#D8C7AD"}]'::jsonb),
    ('remy-marble-side-table','Remy Marble Side Table','tables','side-tables',760, null,'A pale marble top and fine metal base make an elegant perch for a lamp or a favourite object.','CL-REMY','["Natural Marble","Brass"]'::jsonb,'[{"label":"White Marble","color":"#E8E0D4"},{"label":"Grey Marble","color":"#9B8E82"}]'::jsonb),
    ('ellery-full-length-mirror','Ellery Full-Length Mirror','mirrors','full-length-mirrors',940, null,'A generous full-length mirror with a slim oak frame and a clean, timeless profile.','CL-ELLERY','["Oak Wood","Glass"]'::jsonb,'[{"label":"Natural Oak","color":"#C8A96E"},{"label":"Walnut","color":"#6B4B32"}]'::jsonb),
    ('marin-pleated-shade','Marin Pleated Shade','shades','lamp-shades',220, null,'A softly pleated cotton shade with a classic silhouette for a calm, layered interior.','CL-MARIN','["Cotton"]'::jsonb,'[{"label":"Ivory","color":"#F0EBE0"},{"label":"Oatmeal","color":"#D9C8B1"}]'::jsonb),
    ('luna-pendant','Luna Opal Pendant','lamps','pendant-lights',580, null,'A rounded opal-glass pendant diffuses an even, gentle light over dining tables and quiet corners.','CL-LUNA','["Glass","Brass"]'::jsonb,'[{"label":"Opal & Brass","color":"#F0EBE0"},{"label":"Opal & Black","color":"#3A3530"}]'::jsonb),
    ('mira-round-mirror','Mira Round Mirror','mirrors','wall-mirrors',520, null,'A round, polished-edge mirror that brings light and a calm focal point to any wall.','CL-MIRA','["Glass","Brass"]'::jsonb,'[{"label":"Brass","color":"#C9A362"},{"label":"Silver","color":"#9B8E82"}]'::jsonb),
    ('cole-nesting-tables','Cole Nesting Tables','tables','side-tables',640, null,'Two easy-to-move nesting tables add a useful surface beside a favourite chair or beneath a statement mirror.','CL-COLE','["Natural Ash","Walnut"]'::jsonb,'[{"label":"Natural Ash","color":"#D4B896"},{"label":"Walnut","color":"#6B4B32"}]'::jsonb),
    ('noor-velvet-shade','Noor Velvet Lamp Shade','shades','lamp-shades',260, null,'Soft velvet and a warm-toned lining give this tailored shade a rich finish and an inviting evening glow.','CL-NOOR','["Velvet"]'::jsonb,'[{"label":"Sage","color":"#8FA07E"},{"label":"Cocoa","color":"#6B4B32"}]'::jsonb)
)
insert into public.products(category_id, subcategory_id, name, slug, sku, description, price_bdt, compare_at_price_bdt, inventory_quantity, track_inventory, status, attributes, swatches, published_at)
select department.id, subcategory.id, seed.name, seed.slug, seed.sku, seed.description, seed.price_bdt, seed.compare_at_bdt, 10, true, 'active', jsonb_build_object('materials', seed.materials), seed.swatches, now()
from seed
join public.categories department on department.slug = seed.department and department.parent_id is null
join public.categories subcategory on subcategory.slug = seed.subcategory and subcategory.parent_id = department.id
on conflict (slug) do nothing;

