insert into public.product_images(product_id, public_url, alt_text, image_role, sort_order)
select products.id, media.image_url, products.name, media.role, media.sort_order
from media join public.products on products.slug = media.slug
where not exists (select 1 from public.product_images existing where existing.product_id = products.id and existing.public_url = media.image_url);
